// lib/data/database/tables/events_table.dart
//
// Drift table definition for calendar events (classes, meetings, gym, etc.).

import 'package:drift/drift.dart';

/// Represents a scheduled time block on the calendar.
///
/// Events can be:
/// - Fixed: user-created, never touched by the auto-scheduler.
/// - Auto-scheduled: generated by [AutoScheduler], deleted & recreated on each run.
class Events extends Table {
  /// Primary key.
  IntColumn get id => integer().autoIncrement()();

  /// Globally unique UUID for multi-device cloud synchronization.
  TextColumn get syncId => text().nullable()();

  /// Human-readable title.
  TextColumn get title => text().withLength(min: 1, max: 200)();

  /// Category: schoolwork | work | research | personal | other | <custom>.
  TextColumn get category => text().withDefault(const Constant('other'))();

  /// Sub-type used for prep-time lookup: lecture | meeting | gym | commute | etc.
  TextColumn get eventType => text().nullable()();

  /// UTC start timestamp.
  DateTimeColumn get startTime => dateTime()();

  /// UTC end timestamp.
  DateTimeColumn get endTime => dateTime()();

  /// Whether the event repeats.
  BoolColumn get isRecurring => boolean().withDefault(const Constant(false))();

  /// RFC 5545 RRULE string (e.g. "FREQ=WEEKLY;BYDAY=MO,WE,FR").
  TextColumn get rrule => text().nullable()();

  /// Whether this event needs preparation time blocked before it.
  BoolColumn get requiresPrep => boolean().withDefault(const Constant(false))();

  /// Explicit prep duration in minutes (overrides prepTypeDefaults lookup).
  IntColumn get prepMinutes => integer().nullable()();

  /// True → created by AutoScheduler; False → user-created fixed event.
  BoolColumn get isAutoScheduled =>
      boolean().withDefault(const Constant(false))();

  /// When isAutoScheduled=true, stores the source entity type:
  /// "prep:<eventId>" | "habit:<habitId>"
  TextColumn get autoScheduleSource => text().nullable()();

  /// Optional notes / description.
  TextColumn get notes => text().nullable()();

  /// Soft-delete flag.
  BoolColumn get isDeleted => boolean().withDefault(const Constant(false))();

  /// Creation timestamp.
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();

  /// Last-updated timestamp.
  DateTimeColumn get updatedAt => dateTime().withDefault(currentDateAndTime)();
}
